const D = { scale:1, density:.55, energy:.62, speed:1, morph:.6, sym:6, hue:315, x:.5, y:.5, style:'neon', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const u = Math.min(width, height);
const style = P.style;

function hcss(h, s, b, a) {
  h = ((h % 360) + 360) % 360; s = s / 100; b = b / 100;
  const c = b * s, x = c * (1 - Math.abs(((h / 60) % 2) - 1)), mm = b - c;
  let r, gg, bl;
  if (h < 60) { r = c; gg = x; bl = 0; } else if (h < 120) { r = x; gg = c; bl = 0; }
  else if (h < 180) { r = 0; gg = c; bl = x; } else if (h < 240) { r = 0; gg = x; bl = c; }
  else if (h < 300) { r = x; gg = 0; bl = c; } else { r = c; gg = 0; bl = x; }
  return 'rgba(' + ((r + mm) * 255 | 0) + ',' + ((gg + mm) * 255 | 0) + ',' + ((bl + mm) * 255 | 0) + ',' + a + ')';
}

// seed-dependent variation (inline hash, not p5 random)
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.hoff = fr(1) * 50;
  S.pspin = fr(2) < .5 ? -1 : 1;
  S.mjit = (fr(3) - .5) * 1.4;
  S.roff = fr(4) * TAU;
  S.pha = [];
  for (let k = 0; k < 24; k++) S.pha.push(fr(10 + k) * TAU);
}

// radial gradient stamp (grayscale, built once, size-independent)
if (!S.rg) {
  const RG = 180; S.rg = createGraphics(RG, RG); S.rg.noStroke();
  const gc = S.rg.drawingContext;
  const grd = gc.createRadialGradient(RG / 2, RG / 2, RG * 0.02, RG / 2, RG / 2, RG * 0.6);
  grd.addColorStop(0, 'rgba(255,255,255,1)');
  grd.addColorStop(0.4, 'rgba(140,140,140,1)');
  grd.addColorStop(1, 'rgba(12,12,12,1)');
  gc.fillStyle = grd; gc.fillRect(0, 0, RG, RG);
}

// full-canvas render buffer (cached on size) so alpha composites cleanly
if (!S.fb || S.fbKey !== width + 'x' + height) {
  S.fb = createGraphics(width, height); S.fb.pixelDensity(1);
  S.fb.colorMode(HSB, 360, 100, 100, 100); S.fbKey = width + 'x' + height;
}
const g = S.fb;

function superR(phi, m, n1, n2, n3) {
  const t1 = Math.pow(Math.abs(Math.cos(m * phi * 0.25)), n2);
  const t2 = Math.pow(Math.abs(Math.sin(m * phi * 0.25)), n3);
  let r = Math.pow(t1 + t2, -1 / n1);
  if (!(r < 1.7)) r = (r >= 1.7 ? 1.7 : 0);
  return r;
}

const td = K.t;
const isec = 0.45 + 0.55 * K.intensity;
const morph = P.morph;
const pump = 1 + A.bass * 0.13 + K.pulse * 0.05 * P.energy + K.swell * 0.03;
const Rout = u * (0.12 + 0.40 * P.scale) * pump;
const N = Math.round(3 + P.density * 9);
const SAMP = 148;
const rotBase = K.t * (0.03 + P.speed * 0.05) * S.pspin + S.roff;
const eg = 0.5 + P.energy * 0.85;
const hb = (P.hue + S.hoff + K.section * 14) % 360;

// ---- background fill (whole frame) ----
g.push();
if (style === 'ink') g.background(38, 15, 88);
else if (style === 'blueprint') g.background(218, 72, 15);
else if (style === 'chrome') g.background(hb, 5, 7);
else g.background(hb, 62, 6);
g.pop();

const cov = Math.max(width, height) * 1.7;
if (style === 'ink') {
  // aged-paper vignette: multiply a bright-center stamp so corners darken
  g.push(); g.blendMode(MULTIPLY); g.imageMode(CENTER); g.tint(35, 20, 100);
  g.image(S.rg, width / 2, height / 2, cov, cov); g.blendMode(BLEND); g.pop();
} else {
  // ambient tinted glow ground so the frame carries color/tone edge-to-edge
  g.push(); g.imageMode(CENTER);
  if (style === 'blueprint') g.tint(205, 60, 28);
  else if (style === 'chrome') g.tint(hb, 8, 40);
  else g.tint(hb, 60, 44);
  g.image(S.rg, width / 2, height / 2, cov, cov); g.pop();
}

// ---- nested superformula contours ----
g.push();
g.translate(width * P.x, height * P.y);

for (let k = N - 1; k >= 0; k--) {
  const frac = (k + 1) / N;
  const R = Rout * frac;
  const tk = td * 0.6 + k * 0.6 + S.pha[k % 24];
  const m = Math.max(1.5, P.sym + S.mjit + morph * isec * (3.6 * Math.sin(tk * 0.13) + 2.3 * Math.sin(tk * 0.052 + 1.7)));
  let n1 = 0.72 + morph * 0.85 * Math.sin(tk * 0.091 + 0.5); if (n1 < 0.18) n1 = 0.18;
  const n2 = 1 + morph * isec * (5 + 4.4 * Math.sin(tk * 0.067 + 2.1));
  const n3 = 1 + morph * isec * (5 + 4.4 * Math.cos(tk * 0.074 + 0.4));
  const dir = (k % 2 === 0) ? 1 : -1;
  const rot = rotBase * dir * (1 + k * 0.05) + k * 0.16;
  const rh = (hb + k * (12 + morph * 20) + td * 5) % 360;

  const VX = [], VY = [];
  for (let s = 0; s <= SAMP; s++) {
    const a = (s / SAMP) * TAU;
    const rr = R * superR(a, m, n1, n2, n3);
    VX.push(rr * Math.cos(a + rot)); VY.push(rr * Math.sin(a + rot));
  }

  if (style === 'neon') {
    g.noStroke();
    g.fill(rh, 80, 40 + 34 * frac, 8 + 13 * frac * eg);
    g.beginShape(); for (let s = 0; s <= SAMP; s++) g.vertex(VX[s], VY[s]); g.endShape(CLOSE);
    g.blendMode(ADD);
    g.drawingContext.shadowBlur = 8 + 20 * eg + A.rms * 40;
    g.drawingContext.shadowColor = hcss(rh, 70, 100, 0.9);
    g.noFill(); g.stroke(rh, 62, 100, 45 + 30 * frac + A.treble * 40);
    g.strokeWeight(1.1 + 1.7 * eg * frac);
    g.beginShape(); for (let s = 0; s <= SAMP; s++) g.vertex(VX[s], VY[s]); g.endShape(CLOSE);
    g.drawingContext.shadowBlur = 0; g.blendMode(BLEND);
  } else if (style === 'iridescent') {
    g.noStroke(); g.fill(rh, 55, 30 + 20 * frac, 7 + 9 * frac);
    g.beginShape(); for (let s = 0; s <= SAMP; s++) g.vertex(VX[s], VY[s]); g.endShape(CLOSE);
    g.blendMode(ADD); g.strokeWeight(1.3 + 1.2 * frac); g.noFill();
    for (let s = 0; s < SAMP; s++) {
      const a = (s / SAMP) * TAU;
      const ih = (rh + a * 91 + frac * 120 + td * 12) % 360;
      g.stroke(ih, 72, 100, 58);
      g.line(VX[s], VY[s], VX[s + 1], VY[s + 1]);
    }
    g.blendMode(BLEND);
  } else if (style === 'blueprint') {
    g.noFill(); g.strokeWeight(k === N - 1 ? 1.4 : 0.9);
    g.stroke(200, 55, 100, 40 + 40 * frac);
    g.beginShape(); for (let s = 0; s <= SAMP; s++) g.vertex(VX[s], VY[s]); g.endShape(CLOSE);
    if (k === N - 1 || k === 0) {
      g.stroke(200, 45, 90, 20); g.strokeWeight(0.6);
      const spokes = Math.min(16, Math.max(6, Math.round(m)));
      for (let sp = 0; sp < spokes; sp++) {
        const a = sp / spokes * TAU + rot;
        g.line(0, 0, R * 1.02 * Math.cos(a), R * 1.02 * Math.sin(a));
      }
    }
  } else if (style === 'chrome') {
    g.noStroke(); g.fill(0, 0, 14, 12 + 10 * frac);
    g.beginShape(); for (let s = 0; s <= SAMP; s++) g.vertex(VX[s], VY[s]); g.endShape(CLOSE);
    const la = td * 0.4 + 0.7;
    g.strokeWeight(1.1 + 1.4 * frac); g.noFill();
    for (let s = 0; s < SAMP; s++) {
      const a = (s / SAMP) * TAU + rot;
      const spec = Math.max(0, Math.cos(a - la));
      const br = 22 + 70 * spec * spec;
      g.stroke(hb, 6, br, 55);
      g.line(VX[s], VY[s], VX[s + 1], VY[s + 1]);
    }
  } else { // ink-botanical (sumi)
    if (frac > 0.5) { g.noStroke(); g.fill(30, 22, 30, 6); g.beginShape(); for (let s = 0; s <= SAMP; s++) g.vertex(VX[s], VY[s]); g.endShape(CLOSE); }
    g.noFill();
    const ja = S.pha[k % 24];
    for (let s = 0; s < SAMP; s++) {
      const a = (s / SAMP) * TAU;
      const dry = 0.5 + 0.5 * Math.sin(a * 7 + ja);
      const w = (0.5 + 2.4 * frac) * (0.5 + 0.9 * dry);
      const al = 60 + 30 * dry;
      g.stroke(28, 30, 12, al);
      g.strokeWeight(w);
      g.line(VX[s], VY[s], VX[s + 1], VY[s + 1]);
    }
  }
}
g.pop();
g.blendMode(BLEND);

// bright morphing core for the glowing styles (lifts luminance, hypnotic center)
if (style === 'neon' || style === 'iridescent') {
  g.push(); g.blendMode(ADD); g.imageMode(CENTER);
  g.tint((hb + 20) % 360, 50, 46 + A.rms * 30);
  const cc = u * (0.20 + 0.12 * P.scale) * (1 + K.pulse * 0.1 + A.bass * 0.2);
  g.image(S.rg, width * P.x, height * P.y, cc, cc);
  g.blendMode(BLEND); g.pop();
}

// composite to main canvas (alpha for VJ translucency)
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();
blendMode(BLEND);
